/**
 * 点单词浮出的轻量词典卡片。
 *
 * 只管一件事：这个词是什么意思 —— 发音、词性、中文义、英文释义、搭配、例句。
 * 「它在这一段里为什么这样用」交给右侧的 AI 面板（卡片里留一个入口），
 * 所以点词本身不会触发 AI 请求，读起来是轻的。
 */
import {
  Bookmark,
  BookmarkPlus,
  LoaderCircle,
  Sparkles,
  Volume2,
  X,
} from "lucide-react";
import {
  useEffect,
  useLayoutEffect,
  useMemo,
  useRef,
  useState,
  type PointerEvent as ReactPointerEvent,
} from "react";
import { createPortal } from "react-dom";
import type { LanguageInsight } from "@leafia/shared";
import { cn } from "../../lib/cn";
import { lookupWordInsight } from "../../lib/dictionaryLookup";
import {
  clampLookupPosition,
  placeLookupCard,
  type LookupPoint,
} from "../../lib/lookupPlacement";
import { speakEnglish } from "../../lib/speak";
import { useReaderActions } from "./useReaderActions";
import "./word-lookup-folder.css";

/** 被点的那个词在视口里的位置。 */
export interface LookupAnchor {
  left: number;
  top: number;
  right: number;
  bottom: number;
}

export interface WordLookupFolderProps {
  word: string;
  contextBefore: string;
  contextAfter: string;
  /** 卡片自己找位置：贴在词旁边，绝不压住它。传 null 就落在左上角。 */
  anchorRect?: LookupAnchor | null;
  drawer: boolean;
  bookId: string;
  bookLabel: string;
  /**
   * 打开右侧 AI 面板，解释这个词在上下文里的用法。
   * 不传就表示这处没有 AI 面板（比如练习页），卡片上那一格也收起来 ——
   * 词典管「这个词是什么意思」，这句上下文为什么这么用是另一件事。
   */
  onExplain?: (
    word: string,
    contextBefore: string,
    contextAfter: string,
  ) => void;
  onClose: () => void;
}

export function WordLookupFolder({
  word,
  contextBefore,
  contextAfter,
  anchorRect = null,
  drawer,
  bookId,
  bookLabel,
  onExplain,
  onClose,
}: WordLookupFolderProps) {
  const panelRef = useRef<HTMLElement>(null);
  const [loading, setLoading] = useState(false);
  const [result, setResult] = useState<LanguageInsight | null>(null);
  // 卡片摆放：自动落点 / 用户拖到的位置（拖过就听用户的）。
  const [autoPosition, setAutoPosition] = useState<LookupPoint | null>(null);
  const [manualPosition, setManualPosition] = useState<LookupPoint | null>(null);
  const [dragging, setDragging] = useState(false);
  const dragRef = useRef<{
    pointerId: number;
    offsetX: number;
    offsetY: number;
  } | null>(null);
  const { addToReview, saveKnowledgeCard } = useReaderActions({
    bookId,
    bookLabel,
  });

  const requestKey = useMemo(() => `${word}:${bookId}`, [bookId, word]);

  useEffect(() => {
    let cancelled = false;
    setLoading(true);
    setResult(null);

    // 查词怎么走（本机 API → 离线词库 → 在线源 → 兜底）收在 lookupWordInsight 里，
    // 反正结果都落在这张卡片里，不开新页。
    void lookupWordInsight(word).then(({ insight }) => {
      if (cancelled) return;
      setResult(insight);
      setLoading(false);
    });

    return () => {
      cancelled = true;
    };
  }, [requestKey, word]);

  useEffect(() => {
    const onPointerDown = (event: PointerEvent) => {
      if (
        panelRef.current &&
        !panelRef.current.contains(event.target as Node)
      ) {
        onClose();
      }
    };
    const onKeyDown = (event: KeyboardEvent) => {
      if (event.key === "Escape") onClose();
    };
    window.addEventListener("pointerdown", onPointerDown);
    window.addEventListener("keydown", onKeyDown);
    return () => {
      window.removeEventListener("pointerdown", onPointerDown);
      window.removeEventListener("keydown", onKeyDown);
    };
  }, [onClose]);

  // 落点：量出自己的实际大小，摆在词的旁边（下方优先），不压着词也不出屏幕。
  // 卡片查完、标完标注条会长高，所以盯的是自己的尺寸，变一次算一次。
  useLayoutEffect(() => {
    if (drawer || manualPosition) return;
    const element = panelRef.current;
    if (!element) return;
    const update = () => {
      const box = element.getBoundingClientRect();
      const anchor = anchorRect ?? { left: 0, top: 0, right: 0, bottom: 0 };
      const next = placeLookupCard(
        anchor,
        { width: box.width, height: box.height },
        { width: window.innerWidth, height: window.innerHeight },
      );
      setAutoPosition((current) =>
        current && current.left === next.left && current.top === next.top
          ? current
          : next,
      );
    };
    update();
    const observer = new ResizeObserver(update);
    observer.observe(element);
    window.addEventListener("resize", update);
    return () => {
      observer.disconnect();
      window.removeEventListener("resize", update);
    };
  }, [anchorRect, drawer, manualPosition, word]);

  // 拖卡片：抓手是卡片头（按钮除外），拖到哪儿留在哪儿。
  const onGripPointerDown = (event: ReactPointerEvent<HTMLElement>) => {
    if ((event.target as HTMLElement).closest("button, a, input, textarea")) return;
    if (event.pointerType === "mouse" && event.button !== 0) return;
    const element = panelRef.current;
    if (!element) return;
    const box = element.getBoundingClientRect();
    dragRef.current = {
      pointerId: event.pointerId,
      offsetX: event.clientX - box.left,
      offsetY: event.clientY - box.top,
    };
    setDragging(true);
    try {
      event.currentTarget.setPointerCapture(event.pointerId);
    } catch {
      // 不支持捕获的老环境：拖动会拙一点，但照样能拖。
    }
    event.preventDefault();
  };

  const onGripPointerMove = (event: ReactPointerEvent<HTMLElement>) => {
    const drag = dragRef.current;
    const element = panelRef.current;
    if (!drag || drag.pointerId !== event.pointerId || !element) return;
    const box = element.getBoundingClientRect();
    setManualPosition(
      clampLookupPosition(
        { left: event.clientX - drag.offsetX, top: event.clientY - drag.offsetY },
        { width: box.width, height: box.height },
        { width: window.innerWidth, height: window.innerHeight },
      ),
    );
  };

  const endGripDrag = (event: ReactPointerEvent<HTMLElement>) => {
    const drag = dragRef.current;
    if (!drag || drag.pointerId !== event.pointerId) return;
    dragRef.current = null;
    setDragging(false);
  };

  const position = manualPosition ?? autoPosition;

  // 中文义并成一行；线上那条只有英文 —— 第一句顶到第一行，其余收在小字里，
  // 不把同一条释义上下重复两遍。
  const zhLine = result?.meaningsZh.join("；") ?? "";
  const enLines = (result?.definitionEn ?? "")
    .split("\n")
    .map((line) => line.trim())
    .filter(Boolean);
  const mainLine = zhLine || enLines[0] || "";
  const subLine = zhLine ? (result?.definitionEn ?? "") : enLines.slice(1).join("\n");

  // 查的是变形词、拿回来的却是原形（reported → report）：把原形标一句，
  // 免得人以为查错了词。
  const lemma = result?.lemma?.trim() ?? "";
  const baseForm = lemma && lemma.toLowerCase() !== word.trim().toLowerCase() ? lemma : "";

  return createPortal(
    <aside
      ref={panelRef}
      className={cn(
        "word-lookup-folder",
        drawer && "word-lookup-folder--drawer",
        dragging && "is-dragging",
        !drawer && !position && "is-placing",
      )}
      style={
        drawer || !position
          ? undefined
          : { left: position.left, top: position.top }
      }
      role="dialog"
      aria-label={`${word} 的词典卡片`}
    >
      <span className="word-lookup-folder__back" aria-hidden="true" />
      <span className="word-lookup-folder__paper" aria-hidden="true" />
      <div className="word-lookup-folder__front">
        {/* 卡片头就是抓手：按住它可以把卡片拖到顺手的地方。 */}
        <header
          className="word-lookup-folder__grip"
          title="按住拖动卡片"
          onPointerDown={onGripPointerDown}
          onPointerMove={onGripPointerMove}
          onPointerUp={endGripDrag}
          onPointerCancel={endGripDrag}
        >
          <div>
            {/* 出处在卡片头标一句：牛津那条就叫「词典」，线上查来的标「在线词典」。 */}
            <small>{result?.sourceLabel ?? "词典"}</small>
            <strong>{word}</strong>
            {baseForm ? (
              <span className="word-lookup-folder__lemma">原形 {baseForm}</span>
            ) : null}
            {result?.pronunciation ? (
              <span className="word-lookup-folder__pronunciation">
                {result.pronunciation}
              </span>
            ) : null}
          </div>
          <div className="word-lookup-folder__header-actions">
            <button
              type="button"
              aria-label={`朗读 ${word}`}
              onClick={() => speakEnglish(word)}
            >
              <Volume2 size={15} />
            </button>
            <button type="button" onClick={onClose} aria-label="关闭词典卡片">
              <X size={15} />
            </button>
          </div>
        </header>

        <div className="word-lookup-folder__result">
          {loading ? (
            <span className="word-lookup-folder__loading">
              <LoaderCircle size={16} />
              正在查询…
            </span>
          ) : result ? (
            <>
              <div className="word-lookup-folder__meaning">
                <strong>{mainLine}</strong>
                {subLine ? <p>{subLine}</p> : null}
                {(result.partOfSpeech || result.cefr) && (
                  <span className="word-lookup-folder__tags">
                    {[result.partOfSpeech, result.cefr]
                      .filter(Boolean)
                      .map((tag) => (
                        <em key={tag}>{tag}</em>
                      ))}
                  </span>
                )}
              </div>
              {result.collocations.length > 0 && (
                <div className="word-lookup-folder__chips">
                  {result.collocations.slice(0, 4).map((item) => (
                    <span key={item}>{item}</span>
                  ))}
                </div>
              )}
              {result.examples[0] && (
                <blockquote>
                  {result.examples[0].text}
                  {result.examples[0].translationZh && (
                    <small>{result.examples[0].translationZh}</small>
                  )}
                </blockquote>
              )}
            </>
          ) : (
            <span>暂时没有结果。</span>
          )}
        </div>

        {onExplain && (
          <button
            type="button"
            className="word-lookup-folder__ai"
            onClick={() => onExplain(word, contextBefore, contextAfter)}
          >
            <Sparkles size={14} />
            <span>
              <strong>AI 语境解读</strong>
              <small>它在这一段里为什么这样用</small>
            </span>
          </button>
        )}

        <footer>
          <button
            type="button"
            className="is-primary"
            onClick={() => result && addToReview(result, contextBefore)}
            disabled={!result}
          >
            <Bookmark size={14} />
            收藏到单词本
          </button>
          <button
            type="button"
            disabled={!result}
            onClick={() =>
              result &&
              void saveKnowledgeCard({
                term: word,
                contextBefore,
                contextAfter,
                insight: result,
              })
            }
          >
            <BookmarkPlus size={14} />
            存知识卡
          </button>
        </footer>
      </div>
    </aside>,
    document.body,
  );
}
